package com.immersive.sound.notifications;

import lombok.extern.slf4j.Slf4j;

@Slf4j
public class ChatMessageHandler {
    private final SoundEffectPlayer soundEffectPlayer;
    private final ImmersiveSoundNotificationsConfig config;
    private final ConfigParser configParser;

    ChatMessageHandler(SoundEffectPlayer soundEffectPlayer,
                       ImmersiveSoundNotificationsConfig config,
                       ConfigParser configParser) {
        this.soundEffectPlayer = soundEffectPlayer;
        this.config = config;
        this.configParser = configParser;
    }

    public void onChatMessage(String message) {
        // This file uses .contains because some messages have color text inside them.
        try {
            if (message.contains("The effects of the divine potion have worn off.")) {
                for (int[] sound : this.configParser.parseSoundIdsAndVolumes(this.config.divineSounds())) {
                    this.soundEffectPlayer.playSound(sound[0], sound[1]);
                }
            } else if (message.contains("Your cannon is out of ammo!") || message.contains("Your cannon has broken!")) {
                for (int[] sound : this.configParser.parseSoundIdsAndVolumes(this.config.cannonSounds())) {
                    this.soundEffectPlayer.playSound(sound[0], sound[1]);
                }
            } else if(message.contains("Your bracelet of slaughter prevents your slayer count from decreasing. It then crumbles to dust.")) {
                for (int[] sound : this.configParser.parseSoundIdsAndVolumes(this.config.slaughterBraceletSounds())) {
                    this.soundEffectPlayer.playSound(sound[0], sound[1]);
                }
            }
        }
        catch(Exception e) {
            // user likely has a bad formatted config
            // TODO send a game message or let the user know in some way.
            log.debug("error parsing message or config value: {}", e.toString());
        }
    }
}

package com.immersive.sound.notifications;

import lombok.extern.slf4j.Slf4j;

@Slf4j
public class ConfigParser {
    int[][] parseSoundIdsAndVolumes(String config) {
        String[] tokens = config.split(",");

        // (Rows = total sound ids / 2, Columns = 2)
        int[][] pairs = new int[tokens.length / 2][2];

        for (int i = 0; i < tokens.length; i += 2) {
            pairs[i / 2][0] = Integer.parseInt(tokens[i].trim());
            pairs[i / 2][1] = Integer.parseInt(tokens[i + 1].trim());
        }
        return pairs;
    }
}

package com.immersive.sound.notifications;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("immersivesoundnotifications")
public interface ImmersiveSoundNotificationsConfig extends Config
{
	@ConfigItem(
		keyName = "divineSounds",
		name = "Divine Expired",
		description = "The sounds/volumes to play when a divine potion expires"
	)
	default String divineSounds()
	{
		return "5243,20,2225,10";
	}

	@ConfigItem(
			keyName = "cannonSounds",
			name = "Cannon Ammo",
			description = "The sounds/volumes to play when your cannon runs out of ammo or breaks"
	)
	default String cannonSounds()
	{
		return "3837,10";
	}

	@ConfigItem(
			keyName = "slaughterBraceletSounds",
			name = "Slaughter Bracelet",
			description = "The sounds/volumes to play when your slaughter bracelet breaks"
	)
	default String slaughterBraceletSounds()
	{
		return "2974,15";
	}

	@ConfigItem(
			keyName = "prayerSounds",
			name = "Prayer Sounds",
			description = "The sounds/volumes to play as your prayer gets low"
	)
	default String prayerSounds() { return "9108,30"; }

}

package com.immersive.sound.notifications;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "Immersive Sound Notifications"
)
public class ImmersiveSoundNotificationsPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private transient ClientThread clientThread;

	@Inject
	private ImmersiveSoundNotificationsConfig config;

	private SoundEffectPlayer soundEffectPlayer;
	private ConfigParser configParser;
	private ChatMessageHandler chatMessageHandler;
	private StatChangeHandler statChangeHandler;

	@Override
	protected void startUp() throws Exception
	{
		soundEffectPlayer = new SoundEffectPlayer(client, clientThread);
		configParser = new ConfigParser();
		chatMessageHandler = new ChatMessageHandler(soundEffectPlayer, config, configParser);
		statChangeHandler = new StatChangeHandler(soundEffectPlayer, config, configParser);
		log.debug("Immersive Sound Notifications started!");
	}

	@Override
	protected void shutDown() throws Exception
	{
		log.debug("Immersive Sound Notifications stopped!");
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.SPAM
				&& event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}
		var message = event.getMessage();
		chatMessageHandler.onChatMessage(message);
	}

	@Subscribe
	public void onStatChanged(StatChanged statChanged) {
		this.statChangeHandler.onStatChanged(statChanged);
	}

	@Provides
	ImmersiveSoundNotificationsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ImmersiveSoundNotificationsConfig.class);
	}
}

package com.immersive.sound.notifications;

import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;


public class SoundEffectPlayer {
    private final Client client;
    private final ClientThread clientThread;

    public SoundEffectPlayer(Client client, ClientThread clientThread) {
        this.client = client;
        this.clientThread = clientThread;
    }

    public void playSound(int soundId, int volume) {
        this.clientThread.invokeLater(() -> {
            var userVolume = this.client.getPreferences().getSoundEffectVolume();
            this.client.getPreferences().setSoundEffectVolume(volume);
            this.client.playSoundEffect(soundId, 0);
            this.client.getPreferences().setSoundEffectVolume(userVolume);
        });
    }

}

package com.immersive.sound.notifications;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;

@Slf4j
public class StatChangeHandler {
    private final SoundEffectPlayer soundEffectPlayer;
    private final ImmersiveSoundNotificationsConfig config;
    private final ConfigParser configParser;
    private double lastRecordedPrayerPercent = -1;

    StatChangeHandler(SoundEffectPlayer soundEffectPlayer,
                      ImmersiveSoundNotificationsConfig config,
                      ConfigParser configParser) {
        this.soundEffectPlayer = soundEffectPlayer;
        this.config = config;
        this.configParser = configParser;
    }

    private void handlePrayerChange(StatChanged statChanged) {
        int currentPrayer = statChanged.getBoostedLevel();
        int maxPrayer = statChanged.getLevel();
        double percent = (double) currentPrayer / maxPrayer;

        // Stat change alert can trigger on login. The -1 default stops it from firing.
        if (this.lastRecordedPrayerPercent == -1) {
            this.lastRecordedPrayerPercent = percent;
            return;
        }
        try {
            if (percent > lastRecordedPrayerPercent) {
                // prayer was restored
                this.lastRecordedPrayerPercent = percent;
                return;
            }
            // Under 50% and every 5% diff.
            else if ((percent < .5 && lastRecordedPrayerPercent - percent > 0.05) ||
                    // Under 10% and every 2% diff.
                    (percent < .1 && lastRecordedPrayerPercent - percent > 0.02) ||
                    // prayer ran out, final catch.
                    currentPrayer == 0 ) {
                for (int[] sound : this.configParser.parseSoundIdsAndVolumes(this.config.prayerSounds())) {
                    // Curve the volume based on current prayer %. Reaches max volume at 0 prayer.
                    int volume = (int) Math.round(sound[1] * (1.0 - Math.pow(percent, 1)));
                    log.debug("percent: {} - volume: {}", percent, volume);
                    this.soundEffectPlayer.playSound(sound[0], volume);
                }
                this.lastRecordedPrayerPercent = percent;
            }
        }
        catch(Exception e) {
            // user likely has a bad formatted config
            // TODO send a game message or let the user know in some way.
            log.debug("error parsing message or config value: {}", e.toString());
        }
    }

    public void onStatChanged(StatChanged statChanged) {
       if(statChanged.getSkill() == Skill.PRAYER) {
           this.handlePrayerChange(statChanged);
       }
    }
}

